const raw = $input.item.json;
const SHARED_SECRET = 'YOUR_SHARED_SECRET';

let chatInput, sessionId;

if (raw.headers && raw.body !== undefined) {
  // Came in via the public Website Webhook - verify the shared secret.
  const providedKey = raw.headers['x-api-key'] || raw.headers['X-Api-Key'];
  if (providedKey !== SHARED_SECRET) {
    throw new Error('Unauthorized: missing or invalid x-api-key header');
  }
  chatInput = raw.body.chatInput;
  sessionId = raw.body.sessionId || ('web-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8));
} else {
  // Came in via n8n's own Chat Trigger (internal testing panel).
  chatInput = raw.chatInput;
  sessionId = raw.sessionId;
}

return [{
  json: {
    chatInput,
    sessionId
  }
}];
